/* From Uiverse.io by csemszepp - Tags: simple, material design, pattern */
.__UIV_SCOPE__ .container {
  width: 100%;
  height: 100%;
  position: relative;
  background: #fff;
  filter: contrast(7);
  --mask: linear-gradient(red, rgba(0, 0, 0, 0.45));
}

.__UIV_SCOPE__ .container::before {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  background: radial-gradient(#000, transparent) 0 0/1em 1em space;
  -webkit-mask: var(--mask);
  mask: var(--mask);
  content: "";
}
